use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_fdDisposition: FlightStack::QualifiedFdAndSyncDisposition,
  pub api_qualifiedAttitude: FlightStack::QualifiedAttitude,
  pub api_apGuidanceRequest: FlightStack::ApGuidanceRequestValue,
  pub api_apActiveClearInhibit: bool
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_fdDisposition(container.api_fdDisposition);
  put_qualifiedAttitude(container.api_qualifiedAttitude);
  put_apGuidanceRequest(container.api_apGuidanceRequest);
  put_apActiveClearInhibit(container.api_apActiveClearInhibit);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  fdDisposition: FlightStack::QualifiedFdAndSyncDisposition,
  qualifiedAttitude: FlightStack::QualifiedAttitude,
  apGuidanceRequest: FlightStack::ApGuidanceRequestValue,
  apActiveClearInhibit: bool)
{
  put_fdDisposition(fdDisposition);
  put_qualifiedAttitude(qualifiedAttitude);
  put_apGuidanceRequest(apGuidanceRequest);
  put_apActiveClearInhibit(apActiveClearInhibit);
}

/// setter for IN DataPort
pub fn put_fdDisposition(value: FlightStack::QualifiedFdAndSyncDisposition)
{
  *extern_api::IN_fdDisposition.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_qualifiedAttitude(value: FlightStack::QualifiedAttitude)
{
  *extern_api::IN_qualifiedAttitude.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_apGuidanceRequest(value: FlightStack::ApGuidanceRequestValue)
{
  *extern_api::IN_apGuidanceRequest.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_apActiveClearInhibit(value: bool)
{
  *extern_api::IN_apActiveClearInhibit.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_referenceAndFdState() -> FlightStack::ReferenceAndFdState
{
  return extern_api::OUT_referenceAndFdState.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
